function filterHidden(sheet) {
    const hidden = new Set();
    if (!sheet || !sheet.filterRange || !sheet.filters || !sheet.filters.length) return hidden;
    const a = parseRef(sheet.filterRange.a), b = parseRef(sheet.filterRange.b);
    if (!a || !b) return hidden;
    for (let r = a.row + 1; r <= b.row; r++) {
      let visible = true;
      for (const f of sheet.filters) {
        const cell = sheet.cells[coord(f.col, r)] || '';
        if (!matchFilter(f, cell)) { visible = false; break; }
      }
      if (!visible) hidden.add(r);
    }
    return hidden;
  }

function shiftCols(sheet, atCol, delta) {
    const out = {};
    for (const k of Object.keys(sheet.cells || {})) {
      const p = parseRef(k);
      if (!p) continue;
      let c = p.col;
      if (delta < 0) {
        if (c === atCol) continue;
        if (c > atCol) c -= 1;
      } else if (c >= atCol) c += 1;
      if (c < 0 || c >= COLS) continue;
      out[coord(c, p.row)] = sheet.cells[k];
    }
    sheet.cells = out;
  }

function adjustFormulas(sheet, atRow, deltaRow, atCol, deltaCol) {
    for (const k of Object.keys(sheet.cells || {})) {
      const raw = sheet.cells[k];
      if (!raw || raw.charAt(0) !== '=') continue;
      sheet.cells[k] = adjustRefs(raw, atRow, deltaRow, atCol, deltaCol);
    }
  }

function shiftRules(sheet, atRow, deltaRow, atCol, deltaCol) {
    for (const r of (sheet.validations || [])) {
      const a = parseRef(r.a), b = parseRef(r.b);
      if (!a || !b) continue;
      if (deltaRow) {
        [a, b].forEach(function (p) {
          if (deltaRow > 0) { if (p.row >= atRow) p.row += deltaRow; }
          else if (p.row > atRow) p.row -= 1;
        });
      }
      if (deltaCol) {
        [a, b].forEach(function (p) {
          if (deltaCol > 0) { if (p.col >= atCol) p.col += deltaCol; }
          else if (p.col > atCol) p.col -= 1;
        });
      }
      r.a = coord(Math.min(a.col, b.col), Math.min(a.row, b.row));
      r.b = coord(Math.max(a.col, b.col), Math.max(a.row, b.row));
    }
  }

function adjustPivotRange(w, srcId, atRow, deltaRow, atCol, deltaCol) {
    if (!w || !w.sheets) return;
    for (const s of w.sheets) {
      if (!s.pivot || s.pivot.sourceId !== srcId || !s.pivot.range) continue;
      const a = parseRef(s.pivot.range.a), b = parseRef(s.pivot.range.b);
      if (!a || !b) continue;
      if (deltaRow) {
        [a, b].forEach(function (p) {
          if (deltaRow > 0) { if (p.row >= atRow) p.row += deltaRow; }
          else if (p.row > atRow) p.row -= 1;
        });
      }
      if (deltaCol) {
        [a, b].forEach(function (p) {
          if (deltaCol > 0) { if (p.col >= atCol) p.col += deltaCol; }
          else if (p.col > atCol) p.col -= 1;
        });
      }
      s.pivot.range = {
        a: coord(Math.min(a.col, b.col), Math.min(a.row, b.row)),
        b: coord(Math.max(a.col, b.col), Math.max(a.row, b.row))
      };
    }
  }

function parseRef(s) {
    const m = /^\$?([A-Za-z]{1,3})\$?([0-9]{1,6})$/.exec(String(s == null ? '' : s));
    if (!m) return null;
    const c = colIndex(m[1]);
    if (c < 0) return null;
    return { col: c, row: parseInt(m[2], 10) - 1 };
  }

function colIndex(name) {
    const t = String(name == null ? '' : name).toUpperCase();
    if (!t) return -1;
    let n = 0;
    for (let k = 0; k < t.length; k++) {
      const v = t.charCodeAt(k) - 64;
      if (v < 1 || v > 26) return -1;
      n = n * 26 + v;
    }
    return n - 1;
  }

function colName(i) {
    let s = ''; let n = i + 1;
    while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); }
    return s;
  }

function matchFilter(f, value) {
    if (f.kind === 'values') return f.values.indexOf(value) >= 0;
    const v = String(value == null ? '' : value);
    const want = String(f.value == null ? '' : f.value);
    if (f.cond === 'contains') return v.toLowerCase().indexOf(want.toLowerCase()) >= 0;
    if (f.cond === 'greater') { const a = Number(v), b = Number(want); if (isNaN(a) || isNaN(b)) return false; return a > b; }
    if (f.cond === 'before') { const a = Date.parse(v), b = Date.parse(want); if (isNaN(a) || isNaN(b)) return false; return a < b; }
    if (f.cond === 'empty') return v === '';
    if (f.cond === 'notempty') return v !== '';
    return true;
  }

