function adjustPivotRange(w, srcId, atRow, deltaRow, atCol, deltaCol) {
    if (!w || !w.sheets) return;
    for (const s of w.sheets) {
      if (!s.pivot || s.pivot.sourceId !== srcId || !s.pivot.range) continue;
      const a = parseRef(s.pivot.range.a), b = parseRef(s.pivot.range.b);
      if (!a || !b) continue;
      if (deltaRow) {
        [a, b].forEach(function (p) {
          if (deltaRow > 0) { if (p.row >= atRow) p.row += deltaRow; }
          else if (p.row > atRow) p.row -= 1;
        });
      }
      if (deltaCol) {
        [a, b].forEach(function (p) {
          if (deltaCol > 0) { if (p.col >= atCol) p.col += deltaCol; }
          else if (p.col > atCol) p.col -= 1;
        });
      }
      s.pivot.range = {
        a: coord(Math.min(a.col, b.col), Math.min(a.row, b.row)),
        b: coord(Math.max(a.col, b.col), Math.max(a.row, b.row))
      };
    }
  }

function computePivot(w, sheet) {
    const p = sheet.pivot;
    if (!p) return null;
    const src = w.sheets.find(function (s) { return s.id === p.sourceId; });
    if (!src) return { err: 'Pivot field is no longer available. Select a new field.' };
    const a = parseRef(p.range.a), b = parseRef(p.range.b);
    if (!a || !b) return { err: 'Pivot field is no longer available. Select a new field.' };
    const headers = [], colOf = {};
    for (let c = a.col; c <= b.col; c++) {
      const h = src.cells[coord(c, a.row)] || '';
      headers.push(h);
      colOf[h] = c;
    }
    const rField = p.rows || '', vField = p.values || '', cField = p.columns || '';
    if (rField && headers.indexOf(rField) < 0) return { err: 'Pivot field is no longer available. Select a new field.' };
    if (vField && headers.indexOf(vField) < 0) return { err: 'Pivot field is no longer available. Select a new field.' };
    if (cField && headers.indexOf(cField) < 0) return { err: 'Pivot field is no longer available. Select a new field.' };
    if (!rField || !vField) return null;
    const recs = [];
    for (let r = a.row + 1; r <= b.row; r++) {
      const rec = {};
      let empty = true;
      for (const h of headers) {
        const v = src.cells[coord(colOf[h], r)] || '';
        rec[h] = v;
        if (v !== '') empty = false;
      }
      if (!empty) recs.push(rec);
    }
    const rowKeys = [], colKeys = [];
    for (const rec of recs) {
      if (rowKeys.indexOf(rec[rField]) < 0) rowKeys.push(rec[rField]);
      if (cField && colKeys.indexOf(rec[cField]) < 0) colKeys.push(rec[cField]);
    }
    const method = String(p.method || 'SUM').toUpperCase();
    let numericTotal = false;
    for (const rec of recs) {
      const v = rec[vField];
      if (v !== '' && v != null && !isNaN(Number(v))) { numericTotal = true; break; }
    }
    if ((method === 'SUM' || method === 'AVERAGE') && !numericTotal) return { err: 'Value field requires numeric values' };
    function agg(list) {
      if (method === 'COUNT') {
        let n = 0;
        for (const v of list) if (v !== '' && v != null) n++;
        return n;
      }
      const nums = [];
      for (const v of list) {
        if (v === '' || v == null) continue;
        const n = Number(v);
        if (!isNaN(n)) nums.push(n);
      }
      if (!nums.length) return 0;
      let sum = 0;
      for (const n of nums) sum += n;
      if (method === 'AVERAGE') return sum / nums.length;
      return sum;
    }
    function vals(match) {
      const out = [];
      for (const rec of recs) if (match(rec)) out.push(rec[vField]);
      return out;
    }
    const cells = {};
    if (!cField) {
      cells.A1 = rField;
      cells.B1 = method + ' of ' + vField;
      let i = 2;
      for (const rk of rowKeys) {
        cells['A' + i] = rk;
        cells['B' + i] = fmtNum(agg(vals(function (rec) { return rec[rField] === rk; })));
        i++;
      }
      cells['A' + i] = 'Grand Total';
      cells['B' + i] = fmtNum(agg(vals(function () { return true; })));
    } else {
      cells.A1 = rField;
      colKeys.forEach(function (ck, j) { cells[colName(1 + j) + '1'] = ck; });
      const gt = 1 + colKeys.length;
      cells[colName(gt) + '1'] = 'Grand Total';
      let i = 2;
      for (const rk of rowKeys) {
        cells['A' + i] = rk;
        colKeys.forEach(function (ck, j) {
          cells[colName(1 + j) + i] = fmtNum(agg(vals(function (rec) { return rec[rField] === rk && rec[cField] === ck; })));
        });
        cells[colName(gt) + i] = fmtNum(agg(vals(function (rec) { return rec[rField] === rk; })));
        i++;
      }
      cells['A' + i] = 'Grand Total';
      colKeys.forEach(function (ck, j) {
        cells[colName(1 + j) + i] = fmtNum(agg(vals(function (rec) { return rec[cField] === ck; })));
      });
      cells[colName(gt) + i] = fmtNum(agg(vals(function () { return true; })));
    }
    return { cells: cells };
  }

function shiftRows(sheet, atRow, delta) {
    const out = {};
    for (const k of Object.keys(sheet.cells || {})) {
      const p = parseRef(k);
      if (!p) continue;
      let r = p.row;
      if (delta < 0) {
        if (r === atRow) continue;
        if (r > atRow) r -= 1;
      } else if (r >= atRow) r += 1;
      if (r < 0 || r >= ROWS) continue;
      out[coord(p.col, r)] = sheet.cells[k];
    }
    sheet.cells = out;
  }

function adjustFormulas(sheet, atRow, deltaRow, atCol, deltaCol) {
    for (const k of Object.keys(sheet.cells || {})) {
      const raw = sheet.cells[k];
      if (!raw || raw.charAt(0) !== '=') continue;
      sheet.cells[k] = adjustRefs(raw, atRow, deltaRow, atCol, deltaCol);
    }
  }

function shiftRules(sheet, atRow, deltaRow, atCol, deltaCol) {
    for (const r of (sheet.validations || [])) {
      const a = parseRef(r.a), b = parseRef(r.b);
      if (!a || !b) continue;
      if (deltaRow) {
        [a, b].forEach(function (p) {
          if (deltaRow > 0) { if (p.row >= atRow) p.row += deltaRow; }
          else if (p.row > atRow) p.row -= 1;
        });
      }
      if (deltaCol) {
        [a, b].forEach(function (p) {
          if (deltaCol > 0) { if (p.col >= atCol) p.col += deltaCol; }
          else if (p.col > atCol) p.col -= 1;
        });
      }
      r.a = coord(Math.min(a.col, b.col), Math.min(a.row, b.row));
      r.b = coord(Math.max(a.col, b.col), Math.max(a.row, b.row));
    }
  }

function parseRef(s) {
    const m = /^\$?([A-Za-z]{1,3})\$?([0-9]{1,6})$/.exec(String(s == null ? '' : s));
    if (!m) return null;
    const c = colIndex(m[1]);
    if (c < 0) return null;
    return { col: c, row: parseInt(m[2], 10) - 1 };
  }

function colIndex(name) {
    const t = String(name == null ? '' : name).toUpperCase();
    if (!t) return -1;
    let n = 0;
    for (let k = 0; k < t.length; k++) {
      const v = t.charCodeAt(k) - 64;
      if (v < 1 || v > 26) return -1;
      n = n * 26 + v;
    }
    return n - 1;
  }

function colName(i) {
    let s = ''; let n = i + 1;
    while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); }
    return s;
  }

function fmtNum(n) {
    if (typeof n !== 'number' || !isFinite(n)) return '#NUM!';
    if (Number.isInteger(n)) return String(n);
    return String(Math.round(n * 1e10) / 1e10);
  }

